#include <stdio.h>
#include <stdlib.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

int cmp(const void* a, const void* b) {
    return (*(int*) a) - (*(int*) b);
}

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    int times[n];
    for(int i=0; i<n; i++) {
        scanf("%d", &times[i]);
    }

    qsort(times, n, sizeof(int), cmp);

    int* mArr = (int*) calloc(m, sizeof(int));
    for(int i=0; i<n; i++) {
        mArr[i % m] += times[i];
    }

    int ans = mArr[0];
    for(int i=1; i<m; i++) {
        ans = MAX(ans, mArr[i]);
    }

    printf("%d\n", ans);

    return 0;
}
